.login{display:flex;flex-direction:column;gap:8px;max-width:400px;margin:0 auto;padding:32px;background:#fff;border:1px solid #e0e0e0;border-radius:12px}
.login__title{margin:0 0 8px;font-size:24px;line-height:1.25}
.login__error{margin:0 0 8px;padding:12px 16px;border:1px solid #b91c1c;border-radius:8px;background:#fef2f2;color:#7f1d1d;font-size:14px}
.login__label{font-size:14px;font-weight:600}
.login__input{min-height:44px;padding:12px;border:1px solid #737373;border-radius:8px;font:inherit}
.login__remember{display:flex;gap:8px;align-items:center;min-height:44px;font-size:14px}
.login__submit{min-height:44px;border:0;border-radius:999px;background:#111;color:#fff;font-size:16px;font-weight:600;cursor:pointer}
.login__links{display:flex;justify-content:space-between;gap:16px;margin-top:8px;font-size:14px}
.login__input:focus-visible,.login__submit:focus-visible,.login__remember input:focus-visible,.login__links a:focus-visible{outline:2px solid #1d4ed8;outline-offset:2px}
.login__submit:disabled{opacity:.6;cursor:not-allowed}
